def subtract(a, b):
    # Filter out empty intervals
    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []
    if not b:
        return sorted(a)

    # Merge overlapping/touching intervals in a
    a_sorted = sorted(a)
    a_merged = []
    for start, end in a_sorted:
        if a_merged and a_merged[-1][1] >= start:
            a_merged[-1] = [a_merged[-1][0], max(a_merged[-1][1], end)]
        else:
            a_merged.append([start, end])

    # Merge overlapping/touching intervals in b
    b_sorted = sorted(b)
    b_merged = []
    for start, end in b_sorted:
        if b_merged and b_merged[-1][1] >= start:
            b_merged[-1] = [b_merged[-1][0], max(b_merged[-1][1], end)]
        else:
            b_merged.append([start, end])

    # Subtract b from a
    result = []
    for a_start, a_end in a_merged:
        current_start = a_start
        for b_start, b_end in b_merged:
            if b_end <= current_start:
                # b interval is completely before current segment
                continue
            if b_start >= a_end:
                # b interval is completely after a interval
                break

            # There's an overlap
            if current_start < b_start:
                # Add the part before b
                result.append([current_start, b_start])

            # Move current_start past the b interval
            current_start = max(current_start, b_end)

        # Add any remaining part
        if current_start < a_end:
            result.append([current_start, a_end])

    return result

